INSERT INTO room (id, name, desc_1, desc_2, tagline, image, alt)
VALUES
    (1, 'Escape from the Group Project', 'The deadline is in sixty minutes and somebody has to carry the team. Piece together who did what before the final submission locks you out.', 'Navigate through endless passive-aggressive Slack messages and scrambled slide decks to assemble the final presentation before your grade drops to zero.', 'Five teammates. One deliverable. Zero contributions.', '/images/room-group-project.png', 'Group project members looking bored and listless in a library where they are supposed to be finishing their project'),
    (2, 'The Endless Meeting', 'Trapped in a calendar invite that keeps getting extended, you must crack the cipher hidden within redundant status updates to find the exit door.', 'Fight off sleep and corporate buzzwords as you race against the clock to escape a sync that could have literally been an async Slack chat.', 'This could have been an email.', '/images/room-endless-meeting.png', 'A bland conference room where boredom reigns and dreams go to die'),
    (3, 'The Unhandled Exception', 'A critical system crash has locked you inside the core server rack. Trace the corrupted stack trace to patch the vulnerability before the system melts down.', 'Navigate a labyrinth of cascading null pointer exceptions and endless error logs to debug your way back to safety.', 'Something threw. Nothing caught it.', '/images/room-unhandled-exception.png', 'Stack traces and massive binders of documentation stand between these folks and freedom from this chaotic room'),
    (4, 'Deploy to Production on Friday', 'You pushed code to main right before clocking out for the weekend. Now you have to reverse-engineer a flawless deployment script while alarms blare all around you.', 'Tackle frantic pipeline failures and broken CI/CD builds before Monday morning standup exposes your fatal mistake.', 'What could possibly go wrong?', '/images/room-friday-deploy-to-prod.png', 'Teammates try desperately to roll back the deployment before the entire system crashes'),
    (5, 'The Legacy Codebase', 'Venturing deep into undocumented software written back in 1988, you must decipher cryptic functions and ancient spaghetti code to find the master key.', 'Explore dusty directories and unravel layer upon layer of technical debt to uncover the original developer\'s escape hatch.', 'Archaeology meets software engineering.', '/images/room-legacy-codebase.png', 'A dimly-lit basement server room showing years of poor cable management and probably a FORTRAN 77 manual or two'),
    (6, 'Merge Conflict', 'You and your rival are trapped on opposite branches of a split repository. Resolve the conflicting code lines to merge your paths back together.', 'Survive a barrage of competing git pulls, detached heads, and force-push disasters to clear the staging area.', 'Two branches. One truth.', '/images/room-merge-conflict.png', 'A room split between two git branch diagrams with more than a few conflicts to be resolved'),
    (7, 'Time Warp', 'A catastrophic timezone mismatch has thrown you completely out of sync with the universe. Reset the atomic clocks before you\'re stuck in an infinite loop forever.', 'Jump across broken epoch timestamps and daylight saving time anomalies to restore the chronological order of reality.', 'Bend time or get left behind.', '/images/room-time-warp.png', 'Teammates try to restore order to the temporal nexus by unraveling disastrous mismatches due to daylight saving time');
